package example.transportlab;
import java.nio.file.*;
import java.util.*;
public final class SenderVectors {
 static void check(boolean x){Wire.check(x);}
 static void tests(List<byte[]> r){Sender.CandidateBatcher cb=new Sender.CandidateBatcher(2);check(!cb.add(new byte[]{1},1,0));for(int i=0;i<64;i++)check(cb.add(new byte[]{(byte)i},2,0));check(!cb.add(new byte[]{65},2,0));check(cb.flush(49,false).isEmpty());check(cb.flush(50,false).size()==4);check(cb.flush(51,true).isEmpty());check(!cb.add(new byte[]{1},2,52));Sender s=new Sender(10000);for(byte[] raw:r.subList(0,32))check(s.enqueue(raw,0));check(!s.enqueue(r.get(32),0));check(s.tick(0).size()==32);check(s.tick(499).isEmpty());check(s.tick(500).size()==32);check(s.tick(1500).size()==32);check(s.tick(2000).isEmpty());for(byte[] raw:r.subList(0,32))check(s.ack(Wire.hash(raw)));check(s.enqueue(r.get(32),2000));check(s.tick(2000).size()==1);s.limited(Wire.hash(r.get(32)),2000,9000);check(s.tick(9999).isEmpty());check(s.tick(10000).isEmpty()&&s.timedOut&&s.pending.isEmpty());check(s.backoff(10000,.5)==10500);for(int i=1;i<=1000;i++)s.networkChanged(i);check(s.retryAt==10500);check(s.backoff(10500,.5)==11500);Sender p=new Sender(10000);p.enqueue(r.get(0),0);check(p.tick(0).size()==1);p.limited(Wire.hash(r.get(0)),0,800);check(p.tick(500).isEmpty());check(p.tick(800).size()==1);check(p.tick(1500).size()==1);p.limited(Wire.hash(r.get(0)),10001,5);check(p.tick(10001).isEmpty());}
 public static void main(String[] args)throws Exception{
  check(System.getenv().getOrDefault("REMOTE_AGENT_HOME","").startsWith("/tmp/"));long start=System.nanoTime();Map<String,Wire.Identity> ids=new HashMap<>();List<byte[]> packets=new ArrayList<>();int initialBytes=0,frames=0,bytes=0;
  for(String row:Files.readAllLines(Paths.get(args[0]))){String[] p=row.split("\t");for(int i:new int[]{0,2})if(!ids.containsKey(p[i]))ids.put(p[i],new Wire.Identity(p[i],Long.parseLong(p[i+1])));Wire.Identity a=ids.get(p[0]),z=ids.get(p[2]);byte[] raw=Wire.unhex(p[4]);Wire.Opened o=Wire.open(raw,a,z,1700000000000L);byte[] encoded=Wire.seal(a,z,o.ctx,o.type,o.payload,null,null,null);check(encoded.length==raw.length);Wire.open(encoded,a,z,1700000000000L);packets.add(encoded);initialBytes+=encoded.length;}
  for(int n=0;n<packets.size();n+=32){Sender s=new Sender(10000);for(byte[] raw:packets.subList(n,n+32))check(s.enqueue(raw,0));for(int at:new int[]{0,500,1500})s.tick(at);frames+=s.frames;bytes+=s.bytes;for(byte[] raw:packets.subList(n,n+32))s.ack(Wire.hash(raw));check(s.pending.isEmpty());}tests(packets);
  System.out.printf(Locale.ROOT,"{\"runtime\":\"JVM BC\",\"sender_cases\":7,\"initial_frames\":%d,\"initial_bytes\":%d,\"transmitted_frames\":%d,\"transmitted_bytes\":%d,\"codec_wall_ms\":%.3f}%n",packets.size(),initialBytes,frames,bytes,(System.nanoTime()-start)/1e6);
 }
}
